 "content": "from collections import deque


def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append(cells)
    return comps


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for color in sorted({v for row in grid for v in row if v != 0}):
        comps = _components(grid, color)
        if len(comps) != 4:
            continue
        boxes = []
        for cells in comps:
            boxes.append((min(y for y,x in cells), max(y for y,x in cells),
                          min(x for y,x in cells), max(x for y,x in cells)))
        row_spans = sorted({(b[0], b[1]) for b in boxes})
        col_spans = sorted({(b[2], b[3]) for b in boxes})
        # The four occurrences must occupy the corners of a 2-by-2 arrangement.
        if len(row_spans) != 2 or len(col_spans) != 2 or len({(b[0],b[2]) for b in boxes}) != 4:
            continue
        if {(b[0], b[2]) for b in boxes} != {(r[0],c[0]) for r in row_spans for c in col_spans}:
            continue
        # Join the two same-colored objects in each row and each column;
        # existing intervening objects remain unchanged, only zero gaps are drawn.
        for top, bottom in row_spans:
            pair = sorted((b for b in boxes if (b[0],b[1]) == (top,bottom)), key=lambda b:b[2])
            a, b = pair
            for y in range(top, bottom+1):
                for x in range(a[3]+1, b[2]):
                    if out[y][x] == 0:
                        out[y][x] = color
        for left, right in col_spans:
            pair = sorted((b for b in boxes if (b[2],b[3]) == (left,right)), key=lambda b:b[0])
            a, b = pair
            for x in range(left, right+1):
                for y in range(a[1]+1, b[0]):
                    if out[y][x] == 0:
                        out[y][x] = color
    return out


